var s = (msg.payload || '').toString().trim();
if (s.charAt(0) !== '{') return null;
msg.payload = s;
return msg;

var d   = msg.payload;
var usv = parseFloat(d.usv);
var color = usv > 2.0 ? 'red' : usv > 1.0 ? 'orange' : usv > 0.5 ? 'yellow' : 'green';
var icon  = usv > 2.0 ? 'fa-exclamation-triangle' : 'fa-plane';
var lat   = parseFloat(d.lat);
var lon   = parseFloat(d.lon);

var mapMsg = null;
if (lat !== 0 && lon !== 0) {
    mapMsg = {
        payload: {
            name      : 'drone_live',
            lat       : lat,
            lon       : lon,
            alt       : parseFloat(d.alt),
            icon      : icon,
            iconColor : color,
            layer     : 'Drone Live',
            popup     : '<b>' + usv.toFixed(4) + ' µSv/h</b><br>'
                      + d.cpm + ' CPM<br>'
                      + 'Alt: ' + parseFloat(d.alt).toFixed(1) + ' m<br>'
                      + 'RSSI: ' + d.rssi + ' dBm'
        }
    };
}

return [
    mapMsg,
    { payload: parseInt(d.cpm) },
    { payload: parseFloat(d.usv) },
    { payload: parseFloat(d.alt) },
    { payload: parseInt(d.rssi) }
];

var d         = msg.payload;
var sessionId = flow.get('currentSessionId') || 1;
var now       = new Date().toLocaleString('sv-SE', {
    timeZone: 'Asia/Jakarta'
}).replace(' ', 'T');
var lat  = parseFloat(d.lat);
var lon  = parseFloat(d.lon);
var cpm  = parseFloat(d.cpm);
var usvH = parseFloat(d.usv_h);

var sqlMsg = {
    topic: 'INSERT INTO timed_count (session_id, timestamp, duration_s, pulses, cpm, usv_h, usv_total, lat, lon, alt_m, rssi, snr) VALUES ($session_id, $timestamp, $duration_s, $pulses, $cpm, $usv_h, $usv_total, $lat, $lon, $alt_m, $rssi, $snr);',
    payload: [
        sessionId, now,
        parseFloat(d.dur_s), parseInt(d.pulses),
        cpm, usvH, parseFloat(d.usv_tot),
        lat, lon, parseFloat(d.alt),
        parseInt(d.rssi), parseFloat(d.snr)
    ]
};

var notif = {
    payload: d.dur_s + 's: ' + cpm.toFixed(1) + ' CPM | ' + usvH.toFixed(4) + ' µSv/h'
};

var dotColor = cpm > 100 ? 'red' : cpm > 50 ? 'orange' : cpm > 30 ? 'yellow' : 'green';
var dotSize  = Math.min(40, Math.max(10, Math.round(cpm / 5)));
var markerMsg = null;
if (lat !== 0 && lon !== 0) {
    markerMsg = {
        payload: {
            name      : 'timed_' + d.id,
            lat       : lat,
            lon       : lon,
            icon      : 'fa-circle',
            iconColor : dotColor,
            iconSize  : [dotSize, dotSize],
            layer     : 'Timed Counts',
            popup     : '<b>Timed #' + d.id + '</b><br>'
                      + '<b>' + cpm.toFixed(1) + ' CPM</b><br>'
                      + usvH.toFixed(4) + ' µSv/h<br>'
                      + 'Durasi: ' + d.dur_s + 's | Pulsa: ' + d.pulses + '<br>'
                      + 'Alt: ' + parseFloat(d.alt).toFixed(1) + ' m<br>'
                      + now
        }
    };
}

var heatPoints = flow.get('heatPoints') || [];
if (lat !== 0 && lon !== 0) {
    heatPoints.push({ lat: lat, lon: lon, cpm: cpm });
    flow.set('heatPoints', heatPoints);
}
var maxCPM = Math.max.apply(null, heatPoints.map(function(p){ return p.cpm; }));
if (maxCPM < 1) maxCPM = 1;

var heatMsg = null;
if (heatPoints.length > 0) {
    heatMsg = {
        payload: {
            command : { heatmap: heatPoints.map(function(p){
                return { lat: p.lat, lon: p.lon, intensity: parseFloat((p.cpm / maxCPM).toFixed(3)) };
            })},
            layer: 'Heatmap'
        }
    };
}

var tableRow = {
    'ID'         : d.id,
    'Sesi'       : sessionId,
    'Waktu'      : now.replace('T', ' ').slice(0, 19),
    'Durasi(s)'  : parseFloat(d.dur_s),
    'Pulsa'      : parseInt(d.pulses),
    'CPM'        : cpm.toFixed(1),
    'µSv/h'      : usvH.toFixed(4),
    'Total(µSv)' : parseFloat(d.usv_tot).toFixed(6),
    'Lat'        : lat.toFixed(6),
    'Lon'        : lon.toFixed(6),
    'Alt(m)'     : parseFloat(d.alt).toFixed(1),
    'RSSI'       : parseInt(d.rssi)
};

var tableData = flow.get('tableData') || [];
tableData.unshift(tableRow);
if (tableData.length > 500) tableData = tableData.slice(0, 500);
flow.set('tableData', tableData);

return [sqlMsg, notif, markerMsg, heatMsg, { payload: tableData }];

var d = msg.payload;
if (!d.status) return null;
var text = '';
if (d.status === 'cmd_sending') {
    text = 'Mengirim perintah ' + d.cmd + '... (menunggu konfirmasi)';
} else if (d.status === 'cmd_ack') {
    text = 'Perintah ' + d.cmd + ' diterima drone!';
} else if (d.status === 'cmd_timeout') {
    text = 'TIMEOUT: Perintah ' + d.cmd + ' tidak terkonfirmasi. Coba lagi.';
} else {
    return null;
}
return { payload: text };

var sessionId = (flow.get('currentSessionId') || 1) + 1;
flow.set('currentSessionId', sessionId);
flow.set('heatPoints', []);
flow.set('currentSessionView', sessionId);

var clearMarker = { payload: { command: { clearlayer: 'Timed Counts' } } };
var clearHeat   = { payload: { command: { clearlayer: 'Heatmap' } } };
var infoMsg     = { payload: 'Sesi #' + sessionId + ' dimulai' };

node.send([clearMarker, clearHeat, infoMsg]);
return null;

flow.set('heatPoints', []);
var clearMarker = { payload: { command: { clearlayer: 'Timed Counts' } } };
var clearHeat   = { payload: { command: { clearlayer: 'Heatmap' } } };
return [clearMarker, clearHeat];

var direction = msg.payload;
var current   = flow.get('currentSessionView') || (flow.get('currentSessionId') || 1);
var maxSes    = flow.get('currentSessionId') || 1;

var target;
if (direction === 'prev') {
    target = Math.max(1, current - 1);
} else {
    target = Math.min(maxSes, current + 1);
}

if (target === current) {
    return [null, { payload: 'Tidak ada sesi lagi di arah tersebut' }];
}

flow.set('currentSessionView', target);

msg.topic   = 'SELECT id, timestamp, cpm, usv_h, usv_total, lat, lon, alt_m, duration_s, pulses, rssi FROM timed_count WHERE session_id = ' + target + ' ORDER BY id ASC';
msg.payload    = [];
msg._sessionID = target;
return [msg, null];

var rows = msg.payload;
if (!Array.isArray(rows) || rows.length === 0) {
    return [null, null, { payload: 'Sesi #' + (msg._sessionID || '?') + ' — tidak ada data' }];
}

var maxCPM = Math.max.apply(null, rows.map(function(r){ return parseFloat(r.cpm); }));
if (maxCPM < 1) maxCPM = 1;

flow.set('heatPoints', rows.map(function(r){
    return { lat: parseFloat(r.lat), lon: parseFloat(r.lon), cpm: parseFloat(r.cpm) };
}));

var clearMsgs = [
    { payload: { command: { clearlayer: 'Timed Counts' } } },
    { payload: { command: { clearlayer: 'Heatmap' } } }
];

var markerMsgs = rows.map(function(r) {
    var cpm      = parseFloat(r.cpm);
    var dotColor = cpm > 100 ? 'red' : cpm > 50 ? 'orange' : cpm > 30 ? 'yellow' : 'green';
    var dotSize  = Math.min(40, Math.max(10, Math.round(cpm / 5)));
    return {
        payload: {
            name      : 'timed_' + r.id,
            lat       : parseFloat(r.lat),
            lon       : parseFloat(r.lon),
            icon      : 'fa-circle',
            iconColor : dotColor,
            iconSize  : [dotSize, dotSize],
            layer     : 'Timed Counts',
            popup     : '<b>Timed #' + r.id + '</b><br>'
                      + '<b>' + cpm.toFixed(1) + ' CPM</b><br>'
                      + parseFloat(r.usv_h).toFixed(4) + ' µSv/h<br>'
                      + 'Durasi: ' + r.duration_s + 's | Pulsa: ' + r.pulses + '<br>'
                      + 'Alt: ' + parseFloat(r.alt_m).toFixed(1) + ' m<br>'
                      + r.timestamp
        }
    };
});

var heatMsg = {
    payload: {
        command: { heatmap: rows.map(function(r) {
            return {
                lat       : parseFloat(r.lat),
                lon       : parseFloat(r.lon),
                intensity : parseFloat((parseFloat(r.cpm) / maxCPM).toFixed(3))
            };
        })},
        layer: 'Heatmap'
    }
};

var firstTime = rows[0].timestamp || '';
var infoMsg = {
    payload: 'Sesi #' + msg._sessionID + ' — ' + firstTime.replace('T',' ').slice(0,19)
            + ' (' + rows.length + ' titik)'
};

node.send([clearMsgs, markerMsgs, heatMsg, infoMsg]);
return null;

//var dur = flow.get('duration') || 30;
var dur = flow.get('duration');
msg.payload = JSON.stringify({ cmd: 'timed', duration: parseInt(dur) }) + '\n';
return msg;

var rows = msg.payload;
if (!Array.isArray(rows) || rows.length === 0) {
    flow.set('tableData', []);
    return null;
}
var tableData = rows.map(function(r) {
    return {
        'ID'         : r.id,
        'Sesi'       : r.session_id,
        'Waktu'      : (r.timestamp || '').replace('T',' ').slice(0,19),
        'Durasi(s)'  : r.duration_s,
        'Pulsa'      : r.pulses,
        'CPM'        : parseFloat(r.cpm).toFixed(1),
        'µSv/h'      : parseFloat(r.usv_h).toFixed(4),
        'Total(µSv)' : parseFloat(r.usv_total).toFixed(6),
        'Lat'        : parseFloat(r.lat).toFixed(6),
        'Lon'        : parseFloat(r.lon).toFixed(6),
        'Alt(m)'     : parseFloat(r.alt_m).toFixed(1),
        'RSSI'       : r.rssi
    };
});
flow.set('tableData', tableData);
msg.payload = tableData;
return msg;

var rows = flow.get('tableData') || [];
if (rows.length === 0) {
    msg.payload    = 'Tidak ada data.';
    msg.statusCode = 404;
    msg.headers    = { 'Content-Type': 'text/plain' };
    return msg;
}
var cols  = Object.keys(rows[0]);
var lines = [cols.join(',')];
rows.forEach(function(r) {
    lines.push(cols.map(function(k) {
        var v = r[k] !== undefined ? r[k] : '';
        if (typeof v === 'string' && (v.includes(',') || v.includes('"'))) {
            return '"' + v.replace(/"/g, '""') + '"';
        }
        return v;
    }).join(','));
});
var now = new Date();
var pad = function(n){ return ('0'+n).slice(-2); };
var ts  = now.getFullYear() + pad(now.getMonth()+1) + pad(now.getDate())
        + '_' + pad(now.getHours()) + pad(now.getMinutes());
msg.payload    = lines.join('\n');
msg.statusCode = 200;
msg.headers    = {
    'Content-Type'        : 'text/csv; charset=utf-8',
    'Content-Disposition' : 'attachment; filename="radiasi_' + ts + '.csv"'
};
return msg;
